// b95_smoke_top: smoke design for the Digilent Basys 3 (xc7a35tcpg236-1).
// Generated by tools/board_smoke.py from boards/basys3/board.yaml. Do not edit: change the board file and regenerate.
// A counter on the board clock drives the LEDs; switches invert LEDs, a button inverts LED 0; where the board has a PL UART
// a banner is sent at 115200 baud about every 1.3 s and the receive line flips the top LED. No LED or button polarity is assumed.

module b95_smoke_top (
    input  logic clk,
    output logic [15:0] led,
    input  logic btn,
    input  logic [15:0] sw,
    input  logic uart_rx,
    output logic uart_tx
);
    localparam int CLK_HZ       = 100000000;
    localparam int CLKS_PER_BIT = (CLK_HZ + 57600) / 115200;
    localparam int TOPB         = 26;   // $clog2(CLK_HZ) - 1: this counter bit toggles about once a second

    logic [TOPB:0] cnt = '0;
    always_ff @(posedge clk) cnt <= cnt + 1'b1;

    logic [15:0] sw_s;
    sync2 #(.WIDTH(16)) u_sw (.clk(clk), .rst(1'b0), .d(sw), .q(sw_s));
    logic btn_s;
    sync2 #(.WIDTH(1)) u_btn (.clk(clk), .rst(1'b0), .d(btn), .q(btn_s));
    logic rx_s, rx_prev = 1'b1, rx_flip = 1'b0, rx_armed = 1'b0;
    sync2 #(.WIDTH(1), .RESET_VALUE(1'b1)) u_rx (.clk(clk), .rst(1'b0), .d(uart_rx), .q(rx_s));
    always_ff @(posedge clk) begin
        rx_prev <= rx_s;
        if (cnt[8]) rx_armed <= 1'b1;               // the synchroniser flops power up at 0, which is not a start bit
        if (rx_armed && rx_prev && !rx_s) rx_flip <= ~rx_flip;   // a start bit arrived
    end

    always_comb begin
        led[0] = cnt[TOPB - 0] ^ sw_s[0] ^ btn_s;
        led[1] = cnt[TOPB - 1] ^ sw_s[1];
        led[2] = cnt[TOPB - 2] ^ sw_s[2];
        led[3] = cnt[TOPB - 3] ^ sw_s[3];
        led[4] = cnt[TOPB - 4] ^ sw_s[4];
        led[5] = cnt[TOPB - 5] ^ sw_s[5];
        led[6] = cnt[TOPB - 6] ^ sw_s[6];
        led[7] = cnt[TOPB - 7] ^ sw_s[7];
        led[8] = cnt[TOPB - 8] ^ sw_s[8];
        led[9] = cnt[TOPB - 9] ^ sw_s[9];
        led[10] = cnt[TOPB - 10] ^ sw_s[10];
        led[11] = cnt[TOPB - 11] ^ sw_s[11];
        led[12] = cnt[TOPB - 12] ^ sw_s[12];
        led[13] = cnt[TOPB - 13] ^ sw_s[13];
        led[14] = cnt[TOPB - 14] ^ sw_s[14];
        led[15] = cnt[TOPB - 15] ^ sw_s[15] ^ rx_flip;
    end

    localparam int MSGLEN = 22;
    function automatic logic [7:0] msg_byte(input logic [5:0] i);
        case (i)
            6'd0: msg_byte = 8'h46;   // F
            6'd1: msg_byte = 8'h44;   // D
            6'd2: msg_byte = 8'h41;   // A
            6'd3: msg_byte = 8'h20;   //  
            6'd4: msg_byte = 8'h73;   // s
            6'd5: msg_byte = 8'h6d;   // m
            6'd6: msg_byte = 8'h6f;   // o
            6'd7: msg_byte = 8'h6b;   // k
            6'd8: msg_byte = 8'h65;   // e
            6'd9: msg_byte = 8'h20;   //  
            6'd10: msg_byte = 8'h42;   // B
            6'd11: msg_byte = 8'h61;   // a
            6'd12: msg_byte = 8'h73;   // s
            6'd13: msg_byte = 8'h79;   // y
            6'd14: msg_byte = 8'h73;   // s
            6'd15: msg_byte = 8'h20;   //  
            6'd16: msg_byte = 8'h33;   // 3
            6'd17: msg_byte = 8'h20;   //  
            6'd18: msg_byte = 8'h6f;   // o
            6'd19: msg_byte = 8'h6b;   // k
            6'd20: msg_byte = 8'h0d;   // CR
            6'd21: msg_byte = 8'h0a;   // LF
            default: msg_byte = 8'h00;
        endcase
    endfunction

    logic       go = 1'b0, sending = 1'b0, tx_start = 1'b0, tx_busy;
    logic [5:0] idx = '0;
    logic [7:0] tx_data = '0;
    always_ff @(posedge clk) begin
        go       <= (cnt == '0);
        tx_start <= 1'b0;
        if (!sending) begin
            if (go) begin sending <= 1'b1; idx <= '0; end
        end else if (!tx_busy && !tx_start) begin
            if (idx == 6'(MSGLEN)) sending <= 1'b0;
            else begin tx_data <= msg_byte(idx); tx_start <= 1'b1; idx <= idx + 1'b1; end
        end
    end

    uart_tx #(.CLKS_PER_BIT(CLKS_PER_BIT)) u_tx (.clk(clk), .rst(1'b0), .start(tx_start), .data(tx_data), .busy(tx_busy), .tx(uart_tx));
endmodule
